/**
 * Starting and continuing a course series: a material too large for one
 * course, split (`./plan.ts`, `lib/document/series-split.ts`) into several
 * sequential courses, each generated by its own `generation_runs` row.
 *
 * A series is never started as such: it is discovered mid-run, the moment a
 * run's material-analysis step finds its material over budget
 * (`promoteRunToSeriesFirstPart`, called from `lib/server/generation/run/
 * engine.ts`). That run becomes the series' first part, in place; every
 * later part is created only once the part before it completes
 * (`startNextSeriesPart`, called from the same engine's run-completion
 * path), so at most one of a series' runs is ever active at once.
 */
import type { ConnectableQueryable } from '@openmaic/storage/server/reference';

import type { ParsedDocumentPart } from '@/lib/document/bundle';
import {
  claimPendingSeriesPart,
  createCourseSeries,
  ensureCourseSeriesSchema,
  getCourseSeries,
  listStalledCourseSeries,
  readNextPendingSeriesPart,
  type PendingSeriesPart,
} from '@/lib/persistence/course-series';
import { withSchemaBootstrapLock } from '@/lib/persistence/schema-bootstrap-lock';
import { getServerPersistenceProvider, type ServerPersistenceProvider } from '@/lib/persistence/server-provider';
import {
  ActiveRunLimitError,
  createGenerationRun,
  WaitingRunLimitError,
  type CreateRunOptions,
  type StoredRun,
} from '@/lib/server/generation/run/store';
import type { GenerationRunInput } from '@/lib/server/generation/run/types';

import { planCourseSeries } from './plan';

/**
 * Provisioned lazily, like the generation runs' own schema (`lib/server/
 * generation/run/store.ts`): the first series operation in a process
 * creates or migrates `course_series` under the bootstrap lock, instead of
 * every server-backed deployment's startup path needing to know this
 * feature's table exists.
 */
const SCHEMA_STATE_KEY = Symbol.for('openmaic.course-series.schema');
const schemaState = globalThis as typeof globalThis & {
  [SCHEMA_STATE_KEY]?: { connectionString: string; ready: Promise<void> };
};

async function provider(): Promise<ServerPersistenceProvider> {
  const connectionString = process.env.DATABASE_URL ?? '';
  const persistence = await getServerPersistenceProvider(connectionString);
  const cached = schemaState[SCHEMA_STATE_KEY];
  if (!cached || cached.connectionString !== connectionString) {
    const ready = withSchemaBootstrapLock(
      persistence.pool as unknown as ConnectableQueryable,
      ensureCourseSeriesSchema,
    );
    schemaState[SCHEMA_STATE_KEY] = { connectionString, ready };
    ready.catch(() => {
      if (schemaState[SCHEMA_STATE_KEY]?.ready === ready) delete schemaState[SCHEMA_STATE_KEY];
    });
  }
  await schemaState[SCHEMA_STATE_KEY]!.ready;
  return persistence;
}

/** Forget the provisioned schema (tests that drop it). */
export function resetCourseSeriesSchemaForTests(): void {
  delete schemaState[SCHEMA_STATE_KEY];
}

/** A series' first part's plan: its own ranges, plus every later part's. */
export interface SeriesSplitPlan {
  firstPart: PendingSeriesPart;
  restParts: PendingSeriesPart[];
}

/**
 * Plan a split of `parts`, or null when it fits one course (mirrors
 * {@link planCourseSeries}; kept here too so a caller needs only this
 * module to decide whether a run's material calls for a series at all).
 */
export function planSeriesSplit(
  parts: readonly ParsedDocumentPart[],
  maxChars?: number,
): SeriesSplitPlan | null {
  const planned = planCourseSeries(parts, maxChars);
  if (!planned || planned.length === 0) return null;
  const [firstPart, ...restParts] = planned;
  return { firstPart: firstPart!, restParts };
}

/**
 * Title a series' courses by the run's own requirement, numbered: callers
 * that want a nicer title (the requirement is often long or generic) can
 * build their own and are not required to call this.
 */
export function seriesTitleFromRequirement(requirement: string): string {
  const trimmed = requirement.trim();
  const short = trimmed.length > 80 ? `${trimmed.slice(0, 80)}…` : trimmed;
  return short || 'Course series';
}

/**
 * Create the `course_series` row for a run that just discovered its
 * material needs splitting, and return the patch its own commit applies to
 * become the series' first part: the row exists, with every later part
 * `pending`, before this run's material-analysis step goes on with its own
 * (first) slice.
 */
export async function startCourseSeries(input: {
  ownerId: string;
  title: string;
  materialIds: string[];
  plan: SeriesSplitPlan;
}): Promise<{ seriesId: string }> {
  const { pool } = await provider();
  const row = await createCourseSeries(pool, {
    ownerId: input.ownerId,
    title: input.title,
    materialIds: input.materialIds,
    partCount: 1 + input.plan.restParts.length,
    restParts: input.plan.restParts,
  });
  return { seriesId: row.id };
}

/**
 * A series' own row, for a caller that only needs to read it (the
 * `GET /api/course-series/:id` route): goes through this module's own
 * lazily-bootstrapped `provider()`, like every other `course_series` access,
 * instead of reaching `getServerPersistenceProvider` directly -- a read
 * issued before the table has ever been created by a write must still
 * provision it rather than fail.
 */
export async function getCourseSeriesById(
  ownerId: string,
  seriesId: string,
): ReturnType<typeof getCourseSeries> {
  const { pool } = await provider();
  return getCourseSeries(pool, seriesId, ownerId);
}

/**
 * Called once a series part's run completes: claims the next pending part
 * (if any are left) and starts its run. Best-effort, like the run
 * completion event itself -- a failure here leaves the part in
 * `pending_parts`, to be picked up by a later retry of this call rather than
 * losing it; callers log rather than propagate.
 */
export async function startNextSeriesPart(
  ownerId: string,
  seriesId: string,
  base: Pick<
    GenerationRunInput,
    'requirement' | 'interactive' | 'taskEngine' | 'agents' | 'learnerProfile' | 'voice'
  >,
  limits: Pick<CreateRunOptions, 'maxActiveRunsPerOwner' | 'maxWaitingRunsPerOwner'>,
): Promise<StoredRun | null> {
  const { pool } = await provider();
  const series = await getCourseSeries(pool, seriesId, ownerId);
  if (!series) return null;
  const next = await readNextPendingSeriesPart(pool, seriesId, ownerId);
  if (!next) return null;

  const input: GenerationRunInput = {
    ...base,
    materialIds: series.materialIds,
    // Every part's outline is confirmed on its own: a series run waiting on
    // a human for the second, third, ... part would stall the series on
    // nobody in particular (its owner is not shown it like the first part's
    // own outlineReview choice was, since this run was never a request).
    outlineReview: 'auto',
    seriesContext: { seriesId, order: next.order, textRanges: next.textRanges },
  };
  try {
    return await createGenerationRun(ownerId, input, {
      ...limits,
      series: { seriesId, order: next.order },
      prepare: async (tx) => {
        const claimed = await claimPendingSeriesPart(tx, {
          seriesId,
          ownerId,
          expectedOrder: next.order,
        });
        if (!claimed) throw new SeriesPartAlreadyClaimedError();
      },
    });
  } catch (error) {
    if (error instanceof SeriesPartAlreadyClaimedError) return null;
    throw error;
  }
}

class SeriesPartAlreadyClaimedError extends Error {
  constructor() {
    super('The next course-series part was already claimed or is not ready');
    this.name = 'SeriesPartAlreadyClaimedError';
  }
}

/**
 * Recover series whose predecessor completed without creating its successor.
 * Each candidate is rechecked under the series-row lock by
 * `startNextSeriesPart`; another process winning the race is a harmless no-op.
 */
export async function resumeStalledCourseSeries(
  limits: Pick<CreateRunOptions, 'maxActiveRunsPerOwner' | 'maxWaitingRunsPerOwner'>,
  options: { limit?: number; onError?: (seriesId: string, error: unknown) => void } = {},
): Promise<number> {
  const { pool } = await provider();
  const candidates = await listStalledCourseSeries(pool, options.limit);
  let started = 0;
  for (const candidate of candidates) {
    try {
      const previous = candidate.previousInput as GenerationRunInput;
      const run = await startNextSeriesPart(
        candidate.ownerId,
        candidate.seriesId,
        {
          requirement: previous.requirement,
          interactive: previous.interactive,
          taskEngine: previous.taskEngine,
          agents: previous.agents,
          ...(previous.learnerProfile ? { learnerProfile: previous.learnerProfile } : {}),
          ...(previous.voice ? { voice: previous.voice } : {}),
        },
        limits,
      );
      if (run) started += 1;
    } catch (error) {
      // Capacity is transient: leave the part pending and let a later runner
      // scan retry without logging the same expected condition every poll.
      if (error instanceof ActiveRunLimitError || error instanceof WaitingRunLimitError) continue;
      options.onError?.(candidate.seriesId, error);
    }
  }
  return started;
}

/** A series' course gets a readable, numbered title ("Requirement — Part 2 of 5"). */
export function seriesPartCourseTitle(seriesTitle: string, order: number, partCount: number): string {
  return `${seriesTitle} — Part ${order} of ${partCount}`;
}
